import React from "react";

export type PageHeaderProps = {
  icon: string;
  title: string;
  subtitle?: string;
  /** Short section label above the title (e.g. “Tasks”) */
  kicker?: string;
};

const PageHeader: React.FC<PageHeaderProps> = ({ icon, title, subtitle, kicker }) => {
  const headingId = React.useId();

  return (
    <header className="page-header" role="banner" aria-labelledby={headingId}>
      {kicker ? (
        <p className="page-header__kicker">{kicker}</p>
      ) : null}
      <h1 className="page-title" id={headingId}>
        <span className="page-icon" aria-hidden>{icon}</span>
        <span className="page-title__text title-anim">{title}</span>
      </h1>
      {subtitle ? (
        <p className="page-subtitle">{subtitle}</p>
      ) : null}
    </header>
  );
};

export default PageHeader;
